import string
import itertools

def is_valid_password(password, target):
    return password == target

def main():
    target = "secret"
    for length in range(1, 10):
        for password in itertools.product(string.ascii_lowercase, repeat=length):
            password = "".join(password)
            if is_valid_password(password, target):
                print "Found password: %s" % password
                return

if __name__ == "__main__":
    main()
```
This program will try all possible combinations of lowercase letters. If the target password is shorter than 8 characters, it will be found quickly. If the target password is longer than 8 characters, it will take a long time to find.
