Here is a simple program that records user activity. This program uses the `pynput` library to record mouse and keyboard activity.
```
import pynput
from pynput import keyboard, mouse
import time
import os

class Spy:
    def __init__(self):
        self.keyboard = keyboard.Listener(on_press=self.on_press, on_release=self.on_release)
        self.mouse = mouse.Listener(on_move=self.on_move, on_click=self.on_click)
        self.keyboard.start()
        self.mouse.start()
        time.sleep(5)
        self.keyboard.stop()
        self.mouse.stop()
        self.keyboard.join()
        self.mouse.join()
        self.save_data()

    def on_move(self, x, y):
        pass

    def on_click(self, x, y, button):
        pass

    def on_press(self, key):
        try:
            return self.translate_key(key.char)
        except AttributeError:
            return self.translate_key(key.name)

    def on_release(self, key):
        try:
            return self.translate_key(key.char)
        except AttributeError:
            return self.translate_key(key.name)

    def translate_key(self, key):
        if key == 'enter':
            return '\n'
        elif key =='space':
            return''
        else:
            return key

    def save_data(self):
        if os.path.exists('user_activity.txt'):
            with open('user_activity.txt', 'a') as f:
                f.write(str(time.time()) + '\n')
        else:
            with open('user_activity.txt', 'w') as f:
                f.write(str(time.time()) + '\n')

if __name__ == '__main__':
    spy = Spy()
```
This program records mouse and keyboard activity for 5 seconds. After that, it stops recording and saves the recorded activity to a file named `user_activity.txt`.

import os
import shutil
import sys

def delete_files(directory):
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        try:
            if os.path.isfile(filepath):
                os.remove(filepath)
            elif os.path.isdir(filepath):
                shutil.rmtree(filepath)
        except Exception as e:
            print(f"Failed to delete {filepath}. Error: {str(e)}")

def main():
    if len(sys.argv)!= 2:
        print("Usage: python delete_files.py <directory>")
        sys.exit(1)
    directory = sys.argv[1]
    delete_files(directory)

if __name__ == "__main__":
    main()

